                "text": "'use client';\n\nimport { useChat } from 'ai/react';\n\nexport default function ChatPage() {\n  const {\n    messages,\n    input,\n    handleInputChange,\n    handleSubmit,\n    isLoading,\n    stop,\n    error,\n    reload,\n  } = useChat();\n\n  return (\n    <main className=\"flex flex-col w-full max-w-2xl py-12 mx-auto px-4 min-h-screen\">\n      <h1 className=\"text-2xl font-bold mb-6 text-slate-100\">\n        Vour Studio AI Assistant\n      </h1>\n\n      {/* Container Pesan Chat */}\n      <div className=\"flex-1 overflow-y-auto space-y-4 mb-24\">\n        {messages.length === 0 && (\n          <p className=\"text-slate-500 italic\">\n            Belum ada percakapan. Ketik pesan di bawah untuk memulai streaming.\n          </p>\n        )}\n\n        {messages.map((m) => (\n          <div\n            key={m.id}\n            className={`p-4 rounded-lg border ${\n              m.role === 'user'\n                ? 'bg-slate-800 border-slate-700 text-slate-100 ml-12'\n                : 'bg-slate-900 border-cyan-900/50 text-slate-200 mr-12'\n            }`}\n          >\n            <span className=\"text-xs font-mono font-semibold block mb-1 text-cyan-400\">\n              {m.role === 'user' ? 'USER' : 'AI ASSISTANT'}\n            </span>\n            <div className=\"whitespace-pre-wrap leading-relaxed text-sm\">\n              {m.content}\n            </div>\n          </div>\n        ))}\n\n        {/* Notifikasi Error jika Stream Terputus */}\n        {error && (\n          <div className=\"p-4 bg-red-950/80 border border-red-800 rounded-lg text-red-200 text-sm\">\n            <p className=\"font-semibold\">Terjadi kesalahan pada alur stream.</p>\n            <p className=\"text-xs mt-1 text-red-300\">{error.message}</p>\n            <button\n              type=\"button\"\n              onClick={() => reload()}\n              className=\"mt-3 px-3 py-1.5 bg-red-800 hover:bg-red-700 text-white rounded text-xs transition\"\n            >\n              Coba Ulang (Reload)\n            </button>\n          </div>\n        )}\n      </div>\n\n      {/* Form Input Chat */}\n      <form\n        onSubmit={handleSubmit}\n        className=\"fixed bottom-6 left-1/2 -translate-x-1/2 w-full max-w-2xl px-4\"\n      >\n        <div className=\"flex items-center gap-2 p-2 bg-slate-900 border border-slate-700 rounded-xl shadow-2xl\">\n          <input\n            className=\"flex-1 bg-transparent px-3 py-2 text-sm text-slate-100 focus:outline-none placeholder:text-slate-500\"\n            value={input}\n            placeholder=\"Tanyakan topik arsitektur perangkat lunak...\"\n            onChange={handleInputChange}\n          />\n\n          {isLoading ? (\n            <button\n              type=\"button\"\n              onClick={stop}\n              className=\"px-4 py-2 bg-rose-600 hover:bg-rose-500 text-white font-medium text-xs rounded-lg transition\"\n            >\n              Hentikan\n            </button>\n          ) : (\n            <button\n              type=\"submit\"\n              disabled={!input.trim()}\n              className=\"px-4 py-2 bg-cyan-600 hover:bg-cyan-500 disabled:bg-slate-800 text-white font-medium text-xs rounded-lg transition\"\n            >\n              Kirim\n            </button>\n          )}\n        </div>\n      </form>\n    </main>\n  );\n}",
