                "text": "const { messages, error, reload } = useChat({\n  onError: (err) => {\n    // Panggil pustaka notifikasi toast seperti react-hot-toast / sonner jika perlu\n    console.warn('Handling client error event:', err.message);\n  },\n  onResponse: (response) => {\n    if (!response.ok) {\n      console.error('Server mengembalikan HTTP Error Code:', response.status);\n    }\n  },\n});",
                "type": "code-highlight",
