                "type": "listitem",
                "value": 3,
                "indent": 0,
                "checked": false,
                "version": 1,
                "children": [
                  {
                    "mode": "normal",
                    "text": "Data Anda sekarang ada di mana?",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 1,
                    "version": 1
                  },
                  {
                    "mode": "normal",
                    "text": " Kalau semuanya masih di beberapa spreadsheet terpisah, dashboard akan memberi dampak lebih cepat daripada halaman baru yang cantik.",
                    "type": "text",
                    "style": "",
                    "detail": 0,
                    "format": 0,
                    "version": 1
                  }
                ]
